  "canvas.generatePrompt":
    "現在のプロジェクトのコードと構造を確認し、ユーザーが独立した分析結果を求めている場合にのみ、洗練された情報密度の高い構造化キャンバスを作成してください。コードベースのマップ、アーキテクチャレビュー、監査、データ中心の調査結果、比較、フロー、タイムライン、リスクに使用し、的を絞った実装やデバッグ、その他の具体的な成果物には使用しないでください。簡潔な要約、対応している場合は 2〜4 個の高信号な統計、関係/フローとリスクのセクション、行番号付きのファイル参照を優先し、コンパクトな表は有用な比較の場合にのみ使用してください。ブロックの順序は階層的に保ち、すべての主張を確認済みのプロジェクトエビデンスに基づかせ、空のブロックや推測のブロックは省き、実際の内容がない場合はツールを呼び出さないでください。すべての表は、可能な場合は具体的な列名と単位、ソース、期間を明記し、それ自体で説明が完結するようにしてください。Canvas ツールは現在のツールリストから正確に 1 回だけ呼び出してください: ネイティブ MCP では canvas_create、組み込み BYOK エージェントでは canvas.create という正式名が公開される場合があります。Canvas ファイルを自分で作成、書き込み、開くことは決してしないでください — Code Work が右パネルにレンダリングします。Canvas ツールが利用できない場合は、その旨を伝えてください。空でないセクション、統計、ファイル参照、表のみを使用し、Canvas をマークダウンの表に置き換えたり、実行可能な UI コードを生成したりしないでください。タイトルと canvasId は現在のシステム言語で簡潔に指定してください。",
