  "settings.squads": "AIチーム",
  "settings.squadsDescription":
    "チーム = ロールのペルソナ + モデル割り当て + 協業ルール。チームを作成し、リーダーと各メンバーにそれぞれモデル（DeepSeek、Claude、GPTなど）を割り当てて、タスクをディスパッチします。リーダーがタスクを分解して作業を割り当て、メンバーが実行し、リーダーが最終結果を返します。必要に応じて、重要な箇所に人間の承認を追加できます。",
